starter:
def ticket(age, has_card):
    # return "Child", "Senior", "Student" or "Adult"
    pass

solution:
def ticket(age, has_card):
    if age < 12:
        return "Child"
    elif age >= 65:
        return "Senior"
    else:
        if has_card:
            return "Student"
        else:
            return "Adult"
